// WebGL2 tier: GLSL ES 3.00 generated by naga from the same WGSL source.
// GPL-3.0-only.
import { FRAGMENT, SAMPLERS, UNIFORM_BLOCK, VERTEX } from "./generated/surface-glsl.js";
import { fetchBitmap, type Pack } from "./pack.js";
import { PARAMS_BYTES, packParams, type SurfaceParams, type SurfaceRenderer } from "./params.js";

function compile(gl: WebGL2RenderingContext, type: number, source: string) {
	const shader = gl.createShader(type)!;
	gl.shaderSource(shader, source);
	gl.compileShader(shader);
	if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
		throw new Error(`GLSL: ${gl.getShaderInfoLog(shader)}`);
	}
	return shader;
}

export async function createWebGL2Renderer(canvas: HTMLCanvasElement, pack: Pack): Promise<SurfaceRenderer | null> {
	const gl = canvas.getContext("webgl2", { alpha: false, antialias: false, premultipliedAlpha: false });
	if (!gl) return null;

	const program = gl.createProgram()!;
	gl.attachShader(program, compile(gl, gl.VERTEX_SHADER, VERTEX));
	gl.attachShader(program, compile(gl, gl.FRAGMENT_SHADER, FRAGMENT));
	gl.linkProgram(program);
	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(`GLSL link: ${gl.getProgramInfoLog(program)}`);
	gl.useProgram(program);

	const bitmaps = await Promise.all([fetchBitmap(pack, "basecolor"), fetchBitmap(pack, "normal"), fetchBitmap(pack, "roughness")]);
	const textures: WebGLTexture[] = [];
	const layout: [keyof typeof SAMPLERS, number][] = [["basecolor", gl.SRGB8_ALPHA8], ["normal", gl.RGBA8], ["roughness", gl.RGBA8]];
	gl.pixelStorei(gl.UNPACK_COLORSPACE_CONVERSION_WEBGL, gl.NONE);
	gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
	gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
	layout.forEach(([name, internal], unit) => {
		const tex = gl.createTexture()!;
		gl.activeTexture(gl.TEXTURE0 + unit);
		gl.bindTexture(gl.TEXTURE_2D, tex);
		gl.texImage2D(gl.TEXTURE_2D, 0, internal, gl.RGBA, gl.UNSIGNED_BYTE, bitmaps[unit]);
		gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.REPEAT);
		gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.REPEAT);
		gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
		gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
		gl.uniform1i(gl.getUniformLocation(program, SAMPLERS[name]), unit);
		textures.push(tex);
		bitmaps[unit].close();
	});

	const ubo = gl.createBuffer()!;
	gl.bindBuffer(gl.UNIFORM_BUFFER, ubo);
	gl.bufferData(gl.UNIFORM_BUFFER, PARAMS_BYTES, gl.DYNAMIC_DRAW);
	gl.uniformBlockBinding(program, gl.getUniformBlockIndex(program, UNIFORM_BLOCK), 0);
	gl.bindBufferBase(gl.UNIFORM_BUFFER, 0, ubo);
	const vao = gl.createVertexArray();
	gl.bindVertexArray(vao);
	const scratch = new Float32Array(16);

	return {
		tier: "webgl2",
		render(params: SurfaceParams) {
			gl.viewport(0, 0, canvas.width, canvas.height);
			gl.bindBuffer(gl.UNIFORM_BUFFER, ubo);
			gl.bufferSubData(gl.UNIFORM_BUFFER, 0, packParams(params, scratch));
			gl.drawArrays(gl.TRIANGLES, 0, 3);
		},
		destroy() {
			for (const t of textures) gl.deleteTexture(t);
			gl.deleteBuffer(ubo);
			gl.deleteVertexArray(vao);
			gl.deleteProgram(program);
		},
	};
}
